CREATE OR REPLACE FUNCTION public.public_product(pid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.products p JOIN public.supplier_profiles s ON s.id=p.supplier_id WHERE p.id=pid AND p.status='published' AND p.non_plastic AND p.material IN ('bagasse','kraft','wood','cardboard','cotton','beeswax') AND s.verification_status='approved' AND public.account_active(s.user_id) AND NOT p.is_demo AND NOT s.is_demo) $$;
CREATE OR REPLACE FUNCTION public.recycling_access(rid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.recycling_requests r WHERE r.id=rid AND (r.buyer_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.recycling_partners p WHERE p.id=r.partner_id AND p.user_id=auth.uid() AND p.approved))) $$;
CREATE POLICY supplier_active_public ON public.supplier_profiles AS RESTRICTIVE FOR SELECT TO anon USING(public.account_active(user_id));
DO $guard$ DECLARE definition text; BEGIN
SELECT pg_get_functiondef('public.admin_verify_supplier(uuid,text)'::regprocedure) INTO definition; definition:=regexp_replace(definition,'BEGIN','BEGIN IF EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=supplier AND user_id=auth.uid()) THEN RAISE EXCEPTION ''Independent supplier reviewer required''; END IF;','i'); EXECUTE definition;
SELECT pg_get_functiondef('public.recycling_action(text,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'WHERE id=(payload->>''partnerId'')::uuid AND approved','WHERE id=(payload->>''partnerId'')::uuid AND approved AND public.account_active(user_id)'); EXECUTE definition;
SELECT pg_get_functiondef('public.recycling_rankings(date)'::regprocedure) INTO definition; definition:=replace(definition,'rb.approved AND rb.public_ranking','rb.approved AND rb.public_ranking AND public.account_active(rb.user_id)'); EXECUTE definition;
END $guard$;
CREATE FUNCTION public.admin_session_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION public.admin_session_allowed() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_session_allowed() TO authenticated;
CREATE POLICY admin_document_review ON public.product_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_order_items_review ON public.order_items FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));